def admin_html() -> bytes:
    values = {
        "__MAX_SOURCE_FILES__": str(MAX_SOURCE_FILES),
        "__MAX_FILE_BYTES__": str(MAX_UPLOAD_FILE_BYTES),
        "__MAX_TOTAL_BYTES__": str(MAX_UPLOAD_TOTAL_BYTES),
        "__MAX_FILE_MIB__": f"{MAX_UPLOAD_FILE_BYTES / (1024 * 1024):g}",
        "__MAX_TOTAL_MIB__": f"{MAX_UPLOAD_TOTAL_BYTES / (1024 * 1024):g}",
    }
    rendered = ADMIN_HTML
    for placeholder, value in values.items():
        rendered = rendered.replace(placeholder, value)
    return rendered.encode("utf-8")


__all__ = ["admin_html"]
